from pathlib import Path
program = '''from collections import deque, Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    frames = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.pop()
                comp.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    z = (y+dy, x+dx)
                    if 0 <= z[0] < h and 0 <= z[1] < w and z not in seen and grid[z[0]][z[1]] == color:
                        seen.add(z)
                        q.append(z)
            r0, r1 = min(y for y,x in comp), max(y for y,x in comp)
            c0, c1 = min(x for y,x in comp), max(x for y,x in comp)
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            border = {(y,x) for y in range(r0,r1+1) for x in range(c0,c1+1)
                      if y in (r0,r1) or x in (c0,c1)}
            if set(comp) == border:
                frames.append((color, r0, r1, c0, c1, border))
    frame_cells = set().union(*(f[5] for f in frames)) if frames else set()
    counts = Counter(grid[r][c] for r in range(h) for c in range(w)
                     if grid[r][c] != 0 and (r,c) not in frame_cells)
    out = [[0]*w for _ in range(h)]
    for color,r0,r1,c0,c1,border in frames:
        for y,x in border:
            out[y][x] = color
        # Interior checkerboard uses the color whose isolated-dot count matches its size.
        need = sum(1 for y in range(r0+1,r1) for x in range(c0+1,c1) if (y-r0-1 + x-c0-1)%2 == 0)
        fill = next((k for k,v in counts.items() if v == need), None)
        if fill is not None:
            for y in range(r0+1,r1):
                for x in range(c0+1,c1):
                    if (y-r0-1 + x-c0-1)%2 == 0:
                        out[y][x] = fill
    return out
'''
